  ('form', 'immigration-special-resident-retirees-visa', 'Form — Special Resident Retiree''s Visa (SRRV)', 12, '{"title":"Start Your SRRV Assessment","description":"Fill out the form below and our team will get back to you with the next steps.","layout":"sections","submitLabel":"Submit SRRV Assessment","privacyNote":"Your information will be used only to assist you with your inquiry.","consent":null,"successTitle":"Assessment Submitted","successMessage":"Thank you for providing your information. Our team will review your inquiry and contact you regarding the next steps.","successActions":[{"label":"Return to Immigration Services","href":"/philippine-immigration-services"},{"label":"Contact Airfair","href":"/#contact"}],"sections":[{"id":"personal","title":"Personal Information","fields":[{"name":"fullName","label":"Full Name","type":"text","required":true,"placeholder":"Juan Dela Cruz"},{"name":"email","label":"Email Address","type":"email","required":true,"placeholder":"youremail@example.com"},{"name":"phone","label":"Phone / WhatsApp Number","type":"tel","required":true,"placeholder":"+63 912 345 6789"},{"name":"nationality","label":"Nationality","type":"country","required":true},{"name":"dateOfBirth","label":"Date of Birth","type":"date","required":true},{"name":"currentCountry","label":"Current Country of Residence","type":"country","required":true}]},{"id":"retirement-information","title":"Retirement Information","fields":[{"name":"currentlyRetired","label":"Are you currently retired?","type":"radio","options":["Yes","No","Planning to retire"],"required":true},{"name":"occupationStatus","label":"What is your current occupation or retirement status?","type":"select","width":"full","required":true,"options":["Retired / Not working","Employed","Self-employed / Business owner","Planning to retire soon","Other"]},{"name":"receivingPension","label":"Are you currently receiving a pension?","type":"radio","options":["Yes","No","Prefer not to say"],"required":true},{"name":"longTermIntent","label":"Are you planning to live in the Philippines long-term?","type":"radio","options":["Yes","No","Still deciding"],"required":true}]},{"id":"immigration-status","title":"Philippines / Immigration Status","fields":[{"name":"currentlyInPH","label":"Are you currently in the Philippines?","type":"yesno","required":true},{"name":"currentVisaType","label":"Current Visa Type","type":"select","options":["9(a) Temporary Visitor / Tourist Visa","9(g) Pre-Arranged Employee Visa","13(a) Immigrant Visa by Marriage","13 Series Immigrant Visa","47(a)(2) Special Non-Immigrant Visa","9(f) Student Visa","SRRV (Special Resident Retiree''s Visa)","Balikbayan Privilege","Visa Waiver","Other / Not Sure"],"required":true,"showWhen":{"field":"currentlyInPH","equals":"Yes"}},{"name":"dateOfArrival","label":"Date of Arrival","type":"date","required":true,"showWhen":{"field":"currentlyInPH","equals":"Yes"}},{"name":"visaExpiration","label":"Visa Expiration Date","type":"date","required":true,"showWhen":{"field":"currentlyInPH","equals":"Yes"}},{"name":"hasACR","label":"Do you have an ACR I-Card?","type":"yesno","required":true,"showWhen":{"field":"currentlyInPH","equals":"Yes"}},{"name":"expectedArrivalDate","label":"Expected Arrival Date","type":"date","required":false,"showWhen":{"field":"currentlyInPH","equals":"No"}},{"name":"previouslyVisitedPH","label":"Have you previously visited the Philippines?","type":"yesno","required":false,"showWhen":{"field":"currentlyInPH","equals":"No"}}]},{"id":"family-dependents","title":"Family / Dependents","fields":[{"name":"spouseIncluded","label":"Will your spouse be included in your residency plans?","type":"radio","options":["Yes","No","Not Sure"],"required":true},{"name":"bringingDependents","label":"Will you be bringing dependents?","type":"yesno","required":true},{"name":"numberOfDependents","label":"Number of Dependents","type":"number","required":false,"showWhen":{"field":"bringingDependents","equals":"Yes"}}]},{"id":"additional","title":"Additional Details","fields":[{"name":"previouslyAppliedSRRV","label":"Have you previously applied for an SRRV?","type":"yesno","required":true},{"name":"helpNeeded","label":"What do you need help with?","type":"select","width":"full","required":true,"options":["Understanding SRRV eligibility","New SRRV application","Documents and requirements","Existing SRRV application","General SRRV consultation","Other"]},{"name":"message","label":"Additional Details / Message","type":"textarea","required":false,"placeholder":"Tell us more about your retirement plans..."}]}]}'::jsonb, null)
