  ('global', 'site', 'Site-wide (header, footer, shared blocks)', 0, '{"browserBar":{"visible":true},"promiseBar":{"items":["✦ Free Cancellation within 24 hrs","Best Price Guarantee","Secure Booking","24/7 Customer Support"]},"logo":{"src":"/airfair_logo_colored.png","alt":"Air Fair Travel & Tours","mediaId":null},"nav":{"items":[{"label":"Home","href":"/#top","highlight":false},{"label":"Our Services","href":"/#our-services","highlight":false},{"label":"Free Assessment","href":"/#assessment","highlight":false},{"label":"Visa & Immigration","href":"/#our-services","highlight":true},{"label":"About Us","href":"/#about","highlight":false},{"label":"Contact","href":"/#contact","highlight":false}],"ctaLabel":"Book Now","ctaHref":"/#contact","searchPlaceholder":"Search visa and immigration services"},"footer":{"blurb":"Your trusted travel partner and visa consultant for unforgettable journeys and hassle-free immigration services.","columns":[{"heading":"COMPANY","links":[{"label":"About Us","href":"#about"},{"label":"Our Team","href":"#about"},{"label":"Careers","href":"#our-services"},{"label":"Blog","href":"#about"},{"label":"Contact Us","href":"#contact"}]},{"heading":"VISA SERVICES","links":[{"label":"Tourist Visa","href":"#our-services"},{"label":"9G Work Visa","href":"#our-services"},{"label":"13A Marriage Visa","href":"#our-services"},{"label":"SRRV / Retirement","href":"#our-services"},{"label":"ACR-I Card","href":"#our-services"},{"label":"Other Services","href":"#our-services"}]}],"contactHeading":"CONTACT US","newsletter":{"heading":"SUBSCRIBE TO OUR NEWSLETTER","body":"Get the latest updates and travel deals.","placeholder":"Your email address","thanks":"Thanks for subscribing!"},"copyright":"© 2025 Air Fair Travel and Tours OPC. All rights reserved.","legalText":"Privacy Policy　 Terms & Conditions"},"shared":{"immigrationHelpCta":{"heading":"Need More Help?","body":"Not sure if this is the right immigration service for you? Our team is here to help.","primaryCta":{"label":"Talk to Our Immigration Team","href":"/#contact"},"secondaryCta":{"label":"View All Immigration Services","href":"/philippine-immigration-services"}},"supportCard":{"heading":"Need Help?","visaDescription":"Talk to our travel specialists for faster assistance.","travelDescription":"Talk to our travel specialists for personalized assistance.","cta":{"label":"Contact Us","href":"/#contact"}},"labels":{"eligibilityHeading":"Who Is This For?","eligibilitySubtext":"This service is for foreign nationals who:","assistanceHeading":"How Airfair Can Help","assistanceSubtext":"We provide end-to-end assistance to make the process smoother for you.","whyChooseHeading":"Why Choose Airfair?","requirementsHeading":"Requirements","faqHeading":"Frequently Asked Questions","visaAboutPrefix":"About the","packageAboutPrefix":"About","packageHighlightsHeading":"Package Highlights","whatsIncludedHeading":"What''s Included","relatedCtaFallback":"Learn More","visaCardCta":"View Requirements","tourCardCta":"View Package","breadcrumbHome":"Home","breadcrumbServices":"Services","breadcrumbImmigration":"Philippine Immigration Services","breadcrumbVisa":"Visa Assistance","breadcrumbTravel":"Travel and Tours"},"chatBubbleLabel":"Contact Air Fair"}}'::jsonb, null),
  ('page', 'home', 'Home', 0, jsonb_set('{"seo":{"title":"","description":"","note":"Homepage title comes from Settings → SEO"},"sections":[{"key":"hero","label":"Hero slider","visible":true,"fields":{"flagLabel":"PHILIPPINES 🇵🇭","featureIcons":["shield-check","file-check","users"],"slides":[{"tag":"Immigration Services","icon":"stamp","headline":"Philippine ","highlight":"Immigration Services","subheading":"Your trusted partner for every visa journey.","description":"Visa, residency, citizenship, documentation, and immigration compliance — handled end-to-end by accredited consultants.","features":["Government-Accredited","End-to-End Processing","Trusted by Thousands"],"cta":{"label":"Explore Immigration Services","href":"/philippine-immigration-services"},"images":[{"src":"https://images.unsplash.com/photo-1563463149242-bd378d9ab05c?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1750941416707-4dff777c67b1?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1581553673739-c4906b5d0de8?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1715927134295-6b1016e28414?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null}]},{"tag":"Most Requested","icon":"landmark","headline":"Special Resident ","highlight":"Retiree''s Visa","subheading":"Retire where the tropics feel like home.","description":"Live in the Philippines permanently — unlimited travel, no annual reporting, and government discounts.","features":["Lifetime Residency","PRA-Accredited Process","Trusted by Retirees"],"cta":{"label":"Start Your SRRV Application","href":"/philippine-immigration-services/special-resident-retirees-visa"},"images":[{"src":"https://images.unsplash.com/photo-1710917554876-9e2ada25f7b4?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1749468373693-a857cdb4579e?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1546068996-8da61faeceaa?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1771533679889-fa1bf5df299a?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null}]},{"tag":"Visa Assistance","icon":"plane","headline":"International Tourist ","highlight":"Visa Assistance","subheading":"Travel the world with confidence.","description":"Schengen, US, UK, Canada, and Japan — we make the tourist visa application process clearer, from requirements to submission.","features":["Expert Application Support","Multiple Destinations","Clear Requirements Checklist"],"cta":{"label":"Get Visa Assistance","href":"#visa-assistance"},"images":[{"src":"https://images.unsplash.com/photo-1765707886539-6d57024ddc2f?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1566800890932-e89159daf3dc?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1696283201322-04ef0aef3c54?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1549813069-a5f8c1dce35f?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null}]},{"tag":"Travel & Tours","icon":"globe","headline":"Travel & ","highlight":"Tours","subheading":"Discover amazing destinations, hassle-free.","description":"Curated travel packages across Asia — from Kuala Lumpur to Jeju Island, with everything handled for you.","features":["Curated Packages","Hassle-Free Travel","Unforgettable Experiences"],"cta":{"label":"Explore Travel Packages","href":"/travel-tours"},"images":[{"src":"https://images.unsplash.com/photo-1529510021255-4a1179e99095?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1761141954476-2921e2e43e99?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1746872269585-d85a03ef2ad2?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://images.unsplash.com/photo-1744705221117-9c726f9497b0?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null}]}],"trustLabel":"Your Trusted Visa & Immigration Partner","trustItems":[{"icon":"plane","label":"Travel"},{"icon":"users","label":"Family"},{"icon":"compass","label":"Opportunity"},{"icon":"heart","label":"A Brighter Tomorrow"}]}},{"key":"accreditations","label":"Accreditation bar","visible":true,"fields":{"label":"Officially Accredited By","itemSubLabel":"Republic of the Philippines","items":[{"logo":{"src":"/dole-logo-v2.png","alt":"National Labor and Deployment","mediaId":null},"label":"National Labor and Deployment"},{"logo":{"src":"/bi-logo-v2.png","alt":"Bureau of Immigration","mediaId":null},"label":"Bureau of Immigration"},{"logo":{"src":"/pra-logo-v2.png","alt":"Philippine Retirement Authority","mediaId":null},"label":"Philippine Retirement Authority"}]}},{"key":"categories","label":"Service categories","visible":true,"fields":{"linkLabel":"View Services","items":[{"title":"Philippine Immigration Services","description":"Visa, residency, citizenship, documentation, and immigration compliance services.","icon":"stamp","href":"/philippine-immigration-services","theme":"green"},{"title":"Special Resident Retiree''s Visa (SRRV)","description":"Live, retire, and enjoy long-term residency in the Philippines.","icon":"landmark","href":"/philippine-immigration-services/special-resident-retirees-visa","theme":"amber"},{"title":"International Tourist Visa Assistance","description":"Travel with confidence. Aitfair helps make the tourist visa application process clearer.","icon":"plane","href":"/visa-assistance/international-tourist-visa","theme":"blue"},{"title":"Travel & Tours","description":"Discover amazing destinations with our carefully curated travel packages.","icon":"globe","href":"/travel-tours","theme":"teal"}]}},{"key":"immigration","label":"Philippine Immigration Services","visible":true,"fields":{"heading":"Philippine Immigration Services","body":"Reliable end-to-end immigration assistance in the Philippines. Our experienced team helps you navigate the process with clarity, compliance, and confidence.","note":"Cards come from Services → Immigration (items with ''Show on homepage'')."}},{"key":"srrv","label":"SRRV banner","visible":true,"fields":{"image":{"src":"/srrv-retire-paradise-2.png","alt":"Retire in Paradise — SRRV Assistance","mediaId":null},"heading":"Special Resident Retiree''s Visa (SRRV)","subheading":"Retire and enjoy long-term residency in the Philippines with expert guidance.","description":"We help qualified foreign nationals and former Filipino citizens process their SRRV application with a smooth, hassle-free experience — from document preparation and requirements checklists to filing with the Philippine Retirement Authority and post-approval support.","benefits":[{"icon":"home","text":"Long-term residency privileges"},{"icon":"plane","text":"Multiple-entry travel benefits"},{"icon":"arrow-right","text":"Easy re-entry to the Philippines"},{"icon":"file-check-2","text":"Reduced documentation requirements"},{"icon":"users","text":"Access to certain benefits and privileges"}],"primaryCta":{"label":"Free Consultation","href":"/philippine-immigration-services/special-resident-retirees-visa#assessment-form"},"secondaryCta":{"label":"Learn More","href":"/philippine-immigration-services/special-resident-retirees-visa"}}},{"key":"visa","label":"International Tourist Visa Assistance","visible":true,"fields":{"heading":"International Tourist Visa Assistance","description":"Explore the world with confidence. We''ll help you with the application process, requirements, and guidance.","viewAll":{"label":"View All Destinations →","href":"/visa-assistance/international-tourist-visa"},"cardIcon":{"src":"/visa-icon.png","alt":"","mediaId":null},"note":"Cards come from Services → Visa destinations marked ''Featured''."}},{"key":"travel","label":"Travel & Tours","visible":true,"fields":{"heading":"Travel & Tours","description":"Discover amazing destinations with our carefully curated travel packages. Unforgettable experiences, hassle-free travel.","viewAll":{"label":"View All Travel Packages →","href":"/travel-tours"},"cardIcon":{"src":"/travel-tours-icon.png","alt":"","mediaId":null},"cardCtaLabel":"View Package","note":"Cards come from Services → Travel packages with ''Show on homepage''."}},{"key":"trustBar","label":"Trust bar","visible":false,"fields":{"items":[{"icon":"shield-check","title":"Government Accredited","text":"PRA, BI & DOLE accredited"},{"icon":"users","title":"Experienced Consultants","text":"Specialists you can trust"},{"icon":"heart","title":"Personalized Guidance","text":"Tailored to your unique goals"},{"icon":"zap","title":"Fast & Reliable Support","text":"We''re here whenever you need us"}]}},{"key":"assessment","label":"Free assessment","visible":true,"fields":{"headingLine1":"Not sure which visa","headingAccent":"you need?","body":"Tell us where you want to go and what you need. Our team will help you understand the next steps.","primaryCta":{"label":"Get an Assessment","href":"#contact"},"secondaryCta":{"label":"Explore visa services","href":"/visa-assistance/international-tourist-visa"},"trustItems":[{"icon":"shield-check","label":"Clear guidance"},{"icon":"file-check","label":"Personalized checklist"},{"icon":"users","label":"Support from start to finish"}],"steps":[{"icon":"message-circle","title":"Tell us your plans","text":"Share your destination and goals."},{"icon":"file-check","title":"Get your checklist","text":"Know the documents and next steps."},{"icon":"users","title":"Move forward with support","text":"Get guidance through the process."}]}},{"key":"testimonials","label":"Testimonials","visible":true,"fields":{"heading":"Trusted by travelers and families alike.","subheading":"Real stories from clients we''ve guided through their visa and immigration journey.","fallbackCategory":"Air Fair Client","stats":{"clientsValue":"+2,500","clientsLabel":"Happy Clients","avatarInitials":["MC","JR","AC"],"ratingValue":"4.9/5","ratingLabel":"Average Rating"},"tagline":"JOURNEYS TO A BRIGHTER TOMORROW","note":"Cards come from Testimonials."}},{"key":"news","label":"News & current events","visible":true,"fields":{"heading":"News & Current Events","body":"Fresh perspectives on travel, tourism, and immigration to keep you connected.","viewAll":{"label":"View all news","href":"/news"},"cardCtaLabel":"Learn more","note":"Curated news and travel resources. Read each article for details and source links."}},{"key":"contact","label":"Contact","visible":true,"fields":{"heading":"Ready to make your travel dreams a reality?","body":"Tell us what you need and our travel experts will get back to you with the best next step.","formKey":"website-contact"}}]}'::jsonb, '{sections,9,fields,heading}', to_jsonb(coalesce((select cb.value from public.content_blocks cb join public.sections s on s.id = cb.section_id join public.pages p on p.id = s.page_id where p.slug = 'home' and s.template_type = 'testimonials' and cb.field_key = 'heading' and nullif(cb.value, '') is not null limit 1), 'Trusted by travelers and families alike.'))), null),
  ('page', 'immigration-hub', 'Philippine Immigration Services', 1, '{"seo":{"title":"Philippine Immigration Services | {businessName}","description":""},"sections":[{"key":"hero","label":"Hero","visible":true,"fields":{"heading":"Philippine Immigration Services","subheading":"Clear guidance and professional assistance for your Philippine immigration needs.","description":"From visa applications and extensions to ACR I-Card assistance and permanent residency, Airfair helps make the immigration process easier to understand and manage.","primaryCta":{"label":"Explore Immigration Services","href":"#services"},"secondaryCta":{"label":"Talk to Our Team","href":"/#contact"},"image":{"src":"https://images.unsplash.com/photo-1563463149242-bd378d9ab05c?auto=format&fit=crop&w=1200&q=80","alt":"Bureau of Immigration, Republic of the Philippines","mediaId":null}}},{"key":"about","label":"About","visible":true,"fields":{"image":{"src":"https://images.unsplash.com/photo-1544396821-4dd40b938ad3?auto=format&fit=crop&w=1200&q=80","alt":"Passport and travel documents","mediaId":null},"heading":"Philippine Immigration Services","paragraphs":["Navigating immigration requirements can involve multiple documents, processes, and government procedures. Airfair provides assistance for individuals, families, retirees, travelers, and foreign nationals who need support with Philippine visa and immigration-related services.","Our team helps guide clients through the required steps, documentation, and application process so they can move forward with greater clarity and convenience."]}},{"key":"services","label":"Services grid","visible":true,"fields":{"heading":"Immigration Services","description":"Explore our range of Philippine immigration services and find the assistance that matches your needs.","cardLinkLabel":"Learn More","note":"Cards come from Services → Immigration (items with ''Show on hub'')."}},{"key":"why","label":"Why choose Airfair","visible":true,"fields":{"heading":"Why Choose Airfair?","description":"Immigration processes can feel complicated. We help make each step easier to understand and manage.","items":[{"icon":"users","title":"Clear Guidance","description":"Understand the requirements and next steps before moving forward."},{"icon":"file-text","title":"Document Assistance","description":"Get guidance in preparing the documents needed for your application."},{"icon":"heart","title":"Personalized Support","description":"Every situation is different, so assistance is based on your specific requirements."},{"icon":"clock","title":"Convenient Process","description":"Our team helps coordinate the process so you can focus on what matters most."}]}},{"key":"cta","label":"Final call to action","visible":true,"fields":{"heading":"Need Help With Your Immigration Requirements?","body":"Tell us what immigration service you need, and our team will help you understand the next steps.","primaryCta":{"label":"Get Immigration Assistance","href":"/#contact"},"secondaryCta":{"label":"Contact Airfair","href":"/#contact"}}}]}'::jsonb, null),
  ('page', 'visa-hub', 'International Tourist Visa Assistance', 2, '{"seo":{"title":"","description":""},"sections":[{"key":"hero","label":"Hero","visible":true,"fields":{"heading":"International Tourist Visa Assistance","description":"Explore the world with confidence. We''ll help you with the application process, requirements, and guidance for your chosen destination.","primaryCta":{"label":"Explore Destinations","href":"#destinations"},"secondaryCta":{"label":"Talk to Our Visa Team","href":"/#contact"},"trustPoints":["Trusted Guidance","Hassle-Free Process","More Travel Possibilities"],"image":{"src":"https://images.unsplash.com/photo-1765707886539-6d57024ddc2f?auto=format&fit=crop&w=1200&q=80","alt":"Traveler with passport and luggage at the airport","mediaId":null}}},{"key":"destinations","label":"Destinations","visible":true,"fields":{"heading":"Where Are You Planning to Travel?","description":"Browse popular destinations and get visa assistance for your next journey.","searchPlaceholder":"Search destination (e.g. Japan, Canada, Schengen)...","regions":["All Destinations","Europe","North America","Asia","Oceania","Middle East","Others"],"emptyText":"No destinations found. Try another search or check back soon."}},{"key":"cantFind","label":"Can''t find your destination","visible":true,"fields":{"heading":"Can''t find your destination?","body":"We assist with tourist visas to many other countries. Get in touch and we''ll guide you.","cta":{"label":"Contact Us","href":"/#contact"}}}]}'::jsonb, null),
  ('page', 'travel-hub', 'Travel & Tours', 3, '{"seo":{"title":"Travel & Tours Packages | {businessName}","description":""},"sections":[{"key":"hero","label":"Hero","visible":true,"fields":{"heading":"Travel & Tours Packages","description":"Explore amazing destinations, customized travel packages, and hassle-free arrangements. We handle the details, so you can focus on making unforgettable memories.","primaryCta":{"label":"Explore Destinations","href":"#destinations"},"secondaryCta":{"label":"Talk to Our Travel Team","href":"/#contact"},"trustPoints":[{"icon":"plane","label":"Trusted Travel Partner"},{"icon":"briefcase","label":"Hassle-Free Process"},{"icon":"headset","label":"Tailored Packages"}]}},{"key":"search","label":"Search bar","visible":true,"fields":{"destinationPlaceholder":"Search destination (e.g. Japan, Bali, Singapore)","dateLabel":"Travel Date","travelersLabel":"Travelers","travelerOptions":["1 Traveler","2 Travelers","3 Travelers","4 Travelers","5+ Travelers"],"buttonLabel":"Search Packages"}},{"key":"destinations","label":"Popular destinations","visible":true,"fields":{"heading":"Popular Destinations","description":"Explore our most in-demand travel destinations.","emptyText":"No destinations found. Try another search."}},{"key":"featured","label":"Featured packages","visible":true,"fields":{"heading":"Featured Travel Packages","description":"Handpicked packages for your next adventure."}},{"key":"promoBanner","label":"Promo banner","visible":true,"fields":{"image":{"src":"/travel-promo-leaderboard.jpg","alt":"Exclusive travel promo — up to 30% off. Book your trip.","mediaId":null},"href":"/#contact"}}]}'::jsonb, null),
  ('page', 'news', 'News & Current Events', 4, '{"seo":{"title":"News & Current Events | Air Fair","description":""},"sections":[{"key":"hero","label":"Heading","visible":true,"fields":{"heading":"Stories worth exploring.","body":"Travel, tourism, and immigration updates to help you go further."}},{"key":"filters","label":"Category filters","visible":true,"fields":{"categories":["All updates","Travel & Events","Immigration","Tourism News"]}},{"key":"latest","label":"More stories","visible":true,"fields":{"heading":"More stories & travel resources","note":"Curated news and travel resources. Read each article for details and source links."}},{"key":"contact","label":"Contact strip","visible":true,"fields":{"heading":"Stay informed, travel with confidence.","body":"Have a question about your next journey? Our team is here to help.","cta":{"label":"Talk to our team","href":"/#contact"}}},{"key":"article","label":"Article page template","visible":true,"fields":{"figcaption":"Illustrative destination imagery from the Air Fair journal.","travelersHeading":"What this means for travelers","takeawaysHeading":"Key takeaways","aheadHeading":"Looking ahead","sourceHeading":"Source & further reading","sourceLinkLabel":"Visit source website","shareHeading":"Share this article","backLabel":"Back to all news","tocHeading":"In this article","exploreHeading":"Explore more","exploreLinks":[{"label":"News & Events","href":"/news"},{"label":"Travel packages","href":"/travel-tours"},{"label":"Visa assistance","href":"/visa-assistance/international-tourist-visa"}],"help":{"heading":"Plan your next journey","body":"Get guidance on travel, visa assistance, and your next adventure.","cta":{"label":"Book a consultation","href":"/#contact"}},"relatedHeading":"More stories you may like","notFound":"Article not found"}}]}'::jsonb, null),
  ('immigration_service', '13a-immigrant-visa', '13A Immigrant Visa by Marriage', 0, '{"slug":"13a-immigrant-visa","title":"13A Immigrant Visa by Marriage","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Assistance for foreign nationals married to Filipino citizens who want to apply for residency in the Philippines.","heroDescription":"Let Airfair help you navigate the requirements and process for your 13A visa application with greater clarity and convenience.","aboutTitle":"What is the 13A Immigrant Visa?","aboutParagraphs":["The 13A Immigrant Visa allows foreign nationals who are legally married to Filipino citizens to live in the Philippines as permanent residents.","This visa grants multiple-entry privileges and is valid indefinitely, provided the marriage remains valid and the required documents are updated."],"eligibility":[{"icon":"heart","text":"Are legally married to a Filipino citizen"},{"icon":"home","text":"Plan to live in the Philippines long-term"},{"icon":"users","text":"Want to build a future with their Filipino spouse in the Philippines"},{"icon":"file-text","text":"Need guidance with the 13A visa application and requirements"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"13A Immigrant Visa by Marriage Assistance | Airfair","description":"Airfair helps foreign spouses of Filipino citizens navigate the 13A Immigrant Visa requirements and application process."},"heroImage":{"src":"https://images.unsplash.com/photo-1563463149242-bd378d9ab05c?auto=format&fit=crop&w=1200&q=80","alt":"13A Immigrant Visa by Marriage","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1544396821-4dd40b938ad3?auto=format&fit=crop&w=1200&q=80","alt":"What is the 13A Immigrant Visa?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"For foreign spouses of Filipino citizens.","homeIcon":"heart","hubIcon":"heart","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-13a-immigrant-visa')),
  ('immigration_service', '9g-working-visa', 'Pre-Arranged Working Visa (9G)', 1, '{"slug":"9g-working-visa","title":"Pre-Arranged Working Visa (9G)","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Immigration assistance for foreign nationals with a job offer or existing employment in the Philippines.","heroDescription":"Airfair helps you prepare the employer documentation, permits, and immigration filings needed to work legally in the Philippines.","aboutTitle":"What is the 9G Pre-Arranged Employee Visa?","aboutParagraphs":["The 9G visa allows foreign nationals with a confirmed job offer from a Philippine-registered company to legally live and work in the country for the duration of their employment.","The application generally requires coordination with your employer, an Alien Employment Permit (AEP), and supporting company documentation."],"eligibility":[{"icon":"briefcase","text":"Have a confirmed job offer from a Philippine employer"},{"icon":"building","text":"Will be employed by a Philippine-registered company"},{"icon":"file-check","text":"Need help securing an Alien Employment Permit (AEP)"},{"icon":"clock","text":"Want to keep their work visa status compliant and active"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Pre-Arranged Working Visa (9G) Assistance | Airfair","description":"Airfair helps foreign professionals process the 9G working visa, AEP, and employer documentation for the Philippines."},"heroImage":{"src":"https://images.unsplash.com/photo-1517935706615-2717063c2225?auto=format&fit=crop&w=1200&q=80","alt":"Pre-Arranged Working Visa (9G)","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1200&q=80","alt":"What is the 9G Pre-Arranged Employee Visa?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Immigration assistance for foreign nationals working in the Philippines.","homeIcon":"briefcase-outline","hubIcon":"briefcase","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-9g-working-visa')),
  ('immigration_service', 'tourist-visa-extension', 'Tourist Visa Extension', 2, '{"slug":"tourist-visa-extension","title":"Tourist Visa Extension","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Assistance for extending your authorized stay in the Philippines.","heroDescription":"Whether your visa is about to expire or has already lapsed, Airfair helps you understand your extension options and file the paperwork correctly.","aboutTitle":"What is a Tourist Visa Extension?","aboutParagraphs":["A tourist visa extension allows foreign visitors to legally remain in the Philippines beyond their initial authorized stay.","Extensions are typically processed with the Bureau of Immigration and vary depending on your nationality, current visa type, and length of stay requested."],"eligibility":[{"icon":"plane","text":"Are currently in the Philippines on a tourist visa"},{"icon":"clock","text":"Want to extend their authorized stay"},{"icon":"alert-triangle","text":"Have an expired or soon-to-expire visa"},{"icon":"file-text","text":"Need guidance on extension requirements and fees"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Tourist Visa Extension Assistance | Airfair","description":"Airfair helps travelers extend their authorized stay in the Philippines with clear, compliant Bureau of Immigration filings."},"heroImage":{"src":"https://images.unsplash.com/photo-1765707886539-6d57024ddc2f?auto=format&fit=crop&w=1200&q=80","alt":"Tourist Visa Extension","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1566800890932-e89159daf3dc?auto=format&fit=crop&w=1200&q=80","alt":"What is a Tourist Visa Extension?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Assistance for extending your authorized stay in the Philippines.","homeIcon":"ticket","hubIcon":"plane","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-tourist-visa-extension')),
  ('immigration_service', 'acr-i-card', 'ACR I-Card', 3, '{"slug":"acr-i-card","title":"ACR I-Card","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Assistance with Alien Certificate of Registration Identity Card requirements.","heroDescription":"From new applications to renewals and replacements, Airfair helps you prepare the requirements for your ACR I-Card.","aboutTitle":"What is the ACR I-Card?","aboutParagraphs":["The Alien Certificate of Registration Identity Card (ACR I-Card) is the official identification issued to registered foreign nationals residing in the Philippines.","It must be renewed periodically and carried at all times, and is often required alongside your visa when transacting with government agencies."],"eligibility":[{"icon":"id-card","text":"Are a registered foreign national in the Philippines"},{"icon":"file-check","text":"Need a new, renewed, or replacement ACR I-Card"},{"icon":"alert-triangle","text":"Have a lost, damaged, or expiring card"},{"icon":"clipboard-check","text":"Need help updating their registration details"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"ACR I-Card Assistance | Airfair","description":"Airfair helps foreign nationals with new ACR I-Card applications, renewals, replacements, and updates in the Philippines."},"heroImage":{"src":"https://images.unsplash.com/photo-1499856871958-5b9627545d1a?auto=format&fit=crop&w=1200&q=80","alt":"ACR I-Card","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1485738422979-f5c462d49f74?auto=format&fit=crop&w=1200&q=80","alt":"What is the ACR I-Card?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Assistance with Alien Certificate of Registration requirements.","homeIcon":"id-card","hubIcon":"id-card","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-acr-i-card')),
  ('immigration_service', 'special-non-immigrant-visa', 'Special Non-Immigrant Visa', 4, '{"slug":"special-non-immigrant-visa","title":"Special Non-Immigrant Visa","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Support for applicable special non-immigrant visa applications.","heroDescription":"Airfair helps investors, missionaries, and other foreign nationals identify and apply for the special non-immigrant visa category that fits their situation.","aboutTitle":"What is a Special Non-Immigrant Visa?","aboutParagraphs":["Special Non-Immigrant Visas cover a range of categories under Philippine immigration law for foreign nationals whose purpose of stay doesn''t fall under standard tourist or work visas — such as treaty traders/investors, missionaries, or those covered by international agreements.","The right category and requirements depend heavily on your specific purpose of stay, so Airfair helps you identify the correct classification before filing."],"eligibility":[{"icon":"scale","text":"Fall under a treaty trader, investor, or international agreement category"},{"icon":"globe","text":"Are a missionary or religious worker in the Philippines"},{"icon":"file-text","text":"Are unsure which special visa category applies to them"},{"icon":"clipboard-check","text":"Need help preparing sponsoring organization documents"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Special Non-Immigrant Visa Assistance | Airfair","description":"Airfair helps foreign nationals identify and apply for the correct special non-immigrant visa category in the Philippines."},"heroImage":{"src":"https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80","alt":"Special Non-Immigrant Visa","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1696283201322-04ef0aef3c54?auto=format&fit=crop&w=1200&q=80","alt":"What is a Special Non-Immigrant Visa?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Support for applicable special non-immigrant visa applications.","homeIcon":"file-check","hubIcon":"file-check","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-special-non-immigrant-visa')),
  ('immigration_service', 'naturalization', 'Naturalization', 5, '{"slug":"naturalization","title":"Naturalization","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Guidance for eligible foreign nationals seeking Philippine citizenship.","heroDescription":"Airfair helps long-term residents understand the naturalization process and prepare the requirements to become a Filipino citizen.","aboutTitle":"What is Naturalization?","aboutParagraphs":["Naturalization is the legal process through which a foreign national who meets residency, character, and other statutory requirements may become a citizen of the Philippines.","Eligibility generally depends on factors such as length of residency, ties to the Philippines, and ability to speak a Philippine language, among other requirements."],"eligibility":[{"icon":"landmark","text":"Have lived in the Philippines long-term"},{"icon":"heart","text":"Are married to a Filipino citizen or have Filipino children"},{"icon":"graduation-cap","text":"Can speak or understand a Philippine language"},{"icon":"file-text","text":"Want guidance on citizenship eligibility and requirements"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Philippine Naturalization Assistance | Airfair","description":"Airfair guides eligible foreign nationals through the requirements and process for Philippine naturalization."},"heroImage":{"src":"https://images.unsplash.com/photo-1710917554876-9e2ada25f7b4?auto=format&fit=crop&w=1200&q=80","alt":"Naturalization","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1546068996-8da61faeceaa?auto=format&fit=crop&w=1200&q=80","alt":"What is Naturalization?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Guidance for eligible foreign nationals seeking Philippine citizenship.","homeIcon":"landmark","hubIcon":"landmark","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-naturalization')),
  ('immigration_service', 'deportation-assistance', 'Deportation Assistance', 6, '{"slug":"deportation-assistance","title":"Deportation Assistance","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Support and guidance for immigration-related deportation matters.","heroDescription":"If you''ve received a deportation order, Notice to Leave, or are facing an active immigration case, Airfair helps you understand your options and next steps.","aboutTitle":"Facing a Deportation or Immigration Case?","aboutParagraphs":["Deportation proceedings and Bureau of Immigration cases can move quickly and carry serious consequences. Airfair helps foreign nationals understand their case status and coordinate the right next steps.","We work with clients to gather documentation, understand deadlines, and connect with appropriate legal support when needed."],"eligibility":[{"icon":"alert-triangle","text":"Have received a deportation order or Notice to Leave"},{"icon":"scale","text":"Have an active or pending immigration case"},{"icon":"shield-check","text":"Need help understanding their current visa status"},{"icon":"clock","text":"Are facing an urgent deadline and need guidance quickly"}],"assistanceItems":[{"icon":"clipboard-check","title":"Case Assessment","description":"Clear review of your current immigration case and status."},{"icon":"file-text","title":"Document Preparation","description":"Assistance gathering and organizing the documents your case needs."},{"icon":"scale","title":"Legal Coordination","description":"Coordination with appropriate legal counsel where needed."},{"icon":"clock","title":"Process Coordination","description":"Help tracking deadlines and following up on your case."}],"seo":{"title":"Deportation Assistance | Airfair","description":"Airfair helps foreign nationals facing deportation orders or immigration cases in the Philippines understand their next steps."},"heroImage":{"src":"https://images.unsplash.com/photo-1750941416707-4dff777c67b1?auto=format&fit=crop&w=1200&q=80","alt":"Deportation Assistance","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1581553673739-c4906b5d0de8?auto=format&fit=crop&w=1200&q=80","alt":"Facing a Deportation or Immigration Case?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Support and guidance for immigration-related deportation matters.","homeIcon":"shield-check","hubIcon":"shield-check","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-deportation-assistance')),
  ('immigration_service', 'visa-reconsideration', 'Petition / Visa Reconsideration', 7, '{"slug":"visa-reconsideration","title":"Petition / Visa Reconsideration","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Assistance involving immigration petitions or reconsideration matters.","heroDescription":"If a visa or immigration application was denied or questioned, Airfair helps you understand the decision and prepare a motion for reconsideration.","aboutTitle":"What is a Petition / Visa Reconsideration?","aboutParagraphs":["A motion for reconsideration allows applicants to formally request a review of a denied or questioned immigration decision.","Airfair helps you review the reason for denial, gather supporting documentation, and prepare a well-organized petition within the applicable deadline."],"eligibility":[{"icon":"alert-triangle","text":"Had a visa or immigration application denied"},{"icon":"file-search","text":"Received a decision they believe was incorrect"},{"icon":"clock","text":"Have a deadline to file a motion for reconsideration"},{"icon":"file-text","text":"Need help preparing a petition or supporting evidence"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Petition & Visa Reconsideration Assistance | Airfair","description":"Airfair helps applicants prepare motions for reconsideration for denied or questioned Philippine visa and immigration decisions."},"heroImage":{"src":"https://images.unsplash.com/photo-1715927134295-6b1016e28414?auto=format&fit=crop&w=1200&q=80","alt":"Petition / Visa Reconsideration","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1549813069-a5f8c1dce35f?auto=format&fit=crop&w=1200&q=80","alt":"What is a Petition / Visa Reconsideration?","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Assistance involving immigration petitions or reconsideration matters.","homeIcon":"gavel","hubIcon":"gavel","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-visa-reconsideration')),
  ('immigration_service', 'consultation', 'Immigration-Related Consultation', 8, '{"slug":"consultation","title":"Immigration-Related Consultation","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Guidance for other immigration concerns and requirements.","heroDescription":"Not sure which service applies to your situation? Tell us about your concern and Airfair''s team will point you in the right direction.","aboutTitle":"General Immigration Consultation","aboutParagraphs":["Sometimes it isn''t clear which visa or immigration process applies to your situation. Airfair offers a general consultation to help you understand your options before moving forward.","Tell us a bit about your concern, and our team will recommend the right next step — whether that''s a specific visa application, an extension, or another immigration service."],"eligibility":[{"icon":"help-circle","text":"Are unsure which immigration service applies to them"},{"icon":"globe","text":"Are exploring options for living, working, or retiring in the Philippines"},{"icon":"message-circle","text":"Want general guidance before starting an application"},{"icon":"users","text":"Need a starting point for their immigration journey"}],"assistanceItems":[{"icon":"briefcase","title":"Requirements Guidance","description":"Clear checklist and explanation of required documents."},{"icon":"file-text","title":"Document Preparation","description":"Assistance in preparing and reviewing your documents."},{"icon":"users","title":"Application Assistance","description":"Support throughout the application process."},{"icon":"clock","title":"Process Coordination","description":"Help with follow-ups and renewals to keep your status active."}],"seo":{"title":"Immigration Consultation | Airfair","description":"Not sure which visa or immigration service you need? Get general guidance from Airfair''s immigration team."},"heroImage":{"src":"https://images.unsplash.com/photo-1749468373693-a857cdb4579e?auto=format&fit=crop&w=1200&q=80","alt":"Immigration-Related Consultation","mediaId":null},"aboutImage":{"src":"https://images.unsplash.com/photo-1771533679889-fa1bf5df299a?auto=format&fit=crop&w=1200&q=80","alt":"General Immigration Consultation","mediaId":null},"heroSecondaryCta":"Talk to Our Team","card":{"description":"Guidance for other immigration concerns and requirements.","homeIcon":"message-circle","hubIcon":"message-circle","showOnHome":true,"showOnHub":true}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-consultation')),
  ('immigration_service', 'special-resident-retirees-visa', 'Special Resident Retiree''s Visa (SRRV)', 109, '{"slug":"special-resident-retirees-visa","title":"Special Resident Retiree''s Visa (SRRV)","titleHighlight":"(SRRV)","category":"Philippine Immigration Services","eyebrow":"PHILIPPINE IMMIGRATION SERVICES","shortDescription":"Retirement residency assistance for eligible foreign nationals planning to make the Philippines their long-term home.","heroDescription":"Airfair helps simplify the SRRV process by guiding you through the requirements, documentation, and application journey.","heroPrimaryCta":"Start Your SRRV Assessment","aboutEyebrow":"ABOUT THIS VISA","aboutTitle":"What is the Special Resident Retiree''s Visa?","aboutParagraphs":["The Special Resident Retiree''s Visa (SRRV) is a residency option designed for eligible foreign nationals who wish to retire in the Philippines and enjoy a long-term stay in the country.","Airfair can assist you in understanding the application process, preparing the necessary documentation, and identifying the next steps based on your situation."],"eligibilityStyle":"checklist","eligibilitySubtext":"The SRRV is ideal for foreign nationals who:","eligibility":[{"text":"Are planning to retire in the Philippines"},{"text":"Are looking for a long-term residency option"},{"text":"Wish to bring their spouse or qualified dependents"},{"text":"Need guidance on the application process and requirements"}],"assistanceSubtext":"We provide end-to-end assistance to make your SRRV application smooth and hassle-free.","assistanceItems":[{"icon":"users","title":"Eligibility Guidance","description":"Help you understand which SRRV option may apply to your situation."},{"icon":"file-text","title":"Document Preparation","description":"Guidance in organizing and preparing application documents."},{"icon":"message-circle","title":"Application Assistance","description":"Support throughout the preparation and submission process."},{"icon":"clock","title":"Process Coordination","description":"Assistance with follow-ups and next steps throughout your application."}],"whyChooseAirfair":{"title":"Why Choose Airfair?","paragraph":"Choosing to retire in a new country is a big decision. At Airfair, we make the process easier by providing clear guidance, practical assistance, and personalized support. Our team is here to help you understand your options and move forward with confidence."},"hideHelpCta":true,"seo":{"title":"Special Resident Retiree''s Visa (SRRV) Assistance | Airfair","description":"Airfair helps eligible foreign nationals understand and apply for the Special Resident Retiree''s Visa (SRRV) in the Philippines."},"heroImage":{"src":"https://images.unsplash.com/photo-1710917554876-9e2ada25f7b4?auto=format&fit=crop&w=1200&q=80","alt":"Special Resident Retiree''s Visa (SRRV)","mediaId":null},"aboutImage":null,"heroSecondaryCta":"Talk to Our Team","card":{"description":"","homeIcon":"","hubIcon":"","showOnHome":false,"showOnHub":false}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'immigration-special-resident-retirees-visa')),
  ('visa_destination', 'japan', 'Japan Tourist Visa', 0, '{"slug":"japan","country":"Japan","countryCode":"JP","flag":"jp","region":"Asia","featured":true,"visaType":"Tourist Visa","title":"Japan Tourist Visa","hubTitle":"Japan Visa","hubDescription":"Explore Japan for tourism, culture, or business.","hubCta":"View Requirements","subtitle":"Explore Japan for tourism, culture, or business.","description":"Experience the beauty of Japan — from its rich culture and modern cities to breathtaking landscapes. We guide you with the latest requirements, helpful tips, and support throughout your application process.","aboutParagraphs":["A Japan Tourist Visa (Temporary Visitor Visa) allows you to visit Japan for tourism, sightseeing, or to visit family and friends. Discover beautiful destinations, experience unique culture, and enjoy world-class attractions."],"highlights":[{"icon":"plane","title":"Tourism & Sightseeing","description":"Explore top destinations."},{"icon":"users","title":"Visit Family & Friends","description":"Reconnect with loved ones."},{"icon":"clock","title":"Short-Term Stay","description":"Usually up to 90 days."},{"icon":"heart","title":"Amazing Experiences","description":"Culture, food, and more."}],"requirements":[{"title":"Valid Passport","icon":"id-card","required":true,"items":["Must be valid for at least 6 months beyond your intended stay","Must have at least 2 blank visa pages"]},{"title":"Visa Application Form","icon":"file-text","required":true,"items":["Duly accomplished and signed application form"]},{"title":"Recent Photos","icon":"file-check","required":true,"items":["4.5cm x 4.5cm, taken within the last 6 months","Plain white background, no glasses or head coverings"]},{"title":"Flight Itinerary","icon":"plane","required":true,"items":["Confirmed round-trip booking or reservation"],"note":"A tentative or reserved itinerary is often accepted — you don''t need to purchase your ticket until the visa is approved."},{"title":"Hotel Accommodation","icon":"home","required":true,"items":["Confirmed hotel booking for your entire stay","Or an invitation letter if staying with family or friends"]},{"title":"Proof of Financial Capacity","icon":"file-text","required":true,"items":["Bank certificate or bank statements (last 3 months)","Income Tax Return (ITR) for self-employed applicants"]},{"title":"Employment / School Documents","icon":"briefcase","required":false,"items":["Certificate of Employment and approved leave","Business registration, if self-employed","School registration, if a student"]},{"title":"Other Supporting Documents","icon":"clipboard-check","required":false,"items":["Invitation letter, if visiting family or friends","PSA documents, if applicable to your purpose of travel"]}],"faqs":[{"question":"How long is the processing time?","answer":"Processing time varies depending on the embassy and your application, but it typically takes a few business days to a few weeks."},{"question":"How long can I stay in Japan?","answer":"Most tourist visas allow a stay of up to 15 or 30 days, depending on the type of visa approved."},{"question":"Is travel insurance required?","answer":"Travel insurance is not always mandatory for a Japan tourist visa, but it is highly recommended and may strengthen your application."},{"question":"Can I apply if I have been to Japan before?","answer":"Yes. Previous travel to Japan does not disqualify you, and a good travel history can support your application."},{"question":"What happens if my application is denied?","answer":"You may reapply after addressing the reasons for denial. Our team can help you review and strengthen your case."}],"seo":{"title":"Japan Tourist Visa Assistance | Airfair Travel and Tours","description":"Airfair helps you prepare the requirements and application process for your Japan Tourist Visa."},"gallery":[{"src":"https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1600&q=80","alt":"","mediaId":null},{"src":"https://im