  ('travel_package', 'toronto-canada', 'Toronto, Canada', 6, '{"variant":"package","showOnHome":false,"place":"","flagCode":"","name":"Toronto, Canada","title":"Toronto, Canada","slug":"toronto-canada","featured":false,"duration":"6D 5N","inclusions":[{"icon":"plane","label":"Flight"},{"icon":"home","label":"Hotel"},{"icon":"users","label":"Tours"}],"price":"₱62,999","subtitle":"Breathtaking Landscapes All Year Round","description":"From the CN Tower''s skyline views to the thundering waters of Niagara Falls, this package covers Toronto''s best city sights and natural wonders nearby.","heroBadge":{"title":"CN Tower","subtitle":"Toronto, Canada"},"aboutParagraphs":["Toronto offers a lively, multicultural city experience with easy access to some of Canada''s most breathtaking natural landscapes. This package covers the city''s highlights along with a trip to Niagara Falls."],"whatsIncluded":["Round-trip flights","5 nights hotel accommodation","Daily breakfast","Guided city and Niagara Falls tour","Airport transfers"],"faqs":[{"question":"What is included in this package?","answer":"Flights, hotel accommodation, and guided tours are included — see the \"What''s Included\" section above for the full list."},{"question":"Can I customize this itinerary?","answer":"Yes. Let us know your preferences and our travel team will help tailor your Toronto trip."},{"question":"What is the best time to visit?","answer":"This varies by season — our travel specialists can recommend the best time to go based on your preferences."},{"question":"Do I need a visa to travel here?","answer":"This depends on your nationality. Our team can help you check your visa requirements before booking."},{"question":"How do I reserve this package?","answer":"Fill out the inquiry form and our travel specialists will get in touch to confirm your booking details."}],"seo":{"title":"Toronto, Canada Travel Package | Airfair Travel and Tours","description":"Book your Toronto getaway with Airfair — flights, hotel, and guided tours included."},"image":{"src":"https://images.unsplash.com/photo-1517935706615-2717063c2225?auto=format&fit=crop&w=800&q=80","alt":"Toronto, Canada","mediaId":null},"packageHighlights":[{"image":{"src":"https://images.unsplash.com/photo-1517935706615-2717063c2225?auto=format&fit=crop&w=700&q=80","alt":"CN Tower","mediaId":null},"title":"CN Tower","description":"Enjoy panoramic views of Toronto."},{"image":{"src":"https://images.unsplash.com/photo-1750941416707-4dff777c67b1?auto=format&fit=crop&w=700&q=80","alt":"Niagara Falls","mediaId":null},"title":"Niagara Falls","description":"Visit one of the world''s most iconic waterfalls."},{"image":{"src":"https://images.unsplash.com/photo-1596422846543-75c6fc197f07?auto=format&fit=crop&w=700&q=80","alt":"Distillery District","mediaId":null},"title":"Distillery District","description":"Explore Toronto''s historic arts district."},{"image":{"src":"https://images.unsplash.com/photo-1710917554876-9e2ada25f7b4?auto=format&fit=crop&w=700&q=80","alt":"City Waterfront","mediaId":null},"title":"City Waterfront","description":"Stroll along Toronto''s scenic waterfront."}],"relatedCard":{"title":"Explore More Destinations","description":"Discover other amazing places and travel packages.","image":{"src":"https://images.unsplash.com/photo-1750941416707-4dff777c67b1?auto=format&fit=crop&w=800&q=80","alt":"","mediaId":null},"ctaLabel":"View All Packages","ctaHref":"/travel-tours"},"poster":{"src":"/travel-posters/toronto-canada.jpg","alt":"Toronto, Canada promotional poster","mediaId":null}}'::jsonb, (select f.id from public.cms_documents f where f.kind = 'form' and f.slug = 'travel-inquiry')),
