  ('news_article', 'phitex-2026', 'PHITEX 2026 puts Philippine tourism in the spotlight', 0, '{"type":"story","slug":"phitex-2026","category":"Travel & Events","date":"September 2026","dateTime":"2026-09","title":"PHITEX 2026 puts Philippine tourism in the spotlight","description":"Connecting local travel businesses with international buyers.","source":"Tourism Promotions Board","initials":"TPB","href":"https://tpb.gov.ph/press_releases/tpb-wraps-up-phitex-2026-with-over-php-500-million-in-sales-leads-up-more-than-20-from-2025/","image":{"src":"https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":null,"article":{"intro":"The Philippine Travel Exchange connects the country''s tourism businesses with international buyers. The 2026 event brought Philippine destinations and travel services into conversations with partners from around the world.","heading":"A platform for Philippine tourism","body":"According to the Tourism Promotions Board, PHITEX 2026 concluded on September 9 at Conrad Manila. It gathered 102 Philippine sellers and 76 foreign buyers from 24 countries, generating more than PHP 594 million in reported sales leads.","takeaway":"Trade events can help local businesses form relationships that support future tours and travel experiences. Sales leads represent potential business, rather than confirmed bookings.","points":["Connects Philippine sellers with international buyers","Creates opportunities for destination partnerships","Showcases Philippine tourism to overseas markets"],"outlook":"For travelers, the event offers a glimpse of the industry''s work behind future itineraries. Contact our team to explore currently available packages."}}'::jsonb, null),
  ('news_article', 'smarter-safer-borders', 'A new chapter for smarter, safer borders', 1, '{"type":"story","slug":"smarter-safer-borders","category":"Immigration","date":"September 14, 2026","dateTime":"2026-09-14","title":"A new chapter for smarter, safer borders","description":"Digital services and more efficient immigration processes.","source":"Bureau of Immigration","initials":"BI","href":"https://immigration.gov.ph/bi-turns-86-charts-path-to-smarter-safer-borders/","image":{"src":"https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":{"src":"/bi-logo-v2.png","alt":"Bureau of Immigration","mediaId":null},"article":{"intro":"The Bureau of Immigration marked its 86th anniversary with a renewed emphasis on modern services and secure borders.","heading":"Modernization in focus","body":"The bureau''s announcement describes digital transformation, stronger border intelligence, and more efficient immigration processes as priorities. The anniversary celebration took place on September 11 at its new building in Pasay City.","takeaway":"These priorities describe the bureau''s direction. They do not, by themselves, announce a change to an individual traveler''s entry requirements.","points":["Digitalization remains a key priority","Efficiency and border security are shared objectives","Check official notices for specific service changes"],"outlook":"Consult the bureau''s official announcement for the full update and check the requirements relevant to your journey before traveling."}}'::jsonb, null),
  ('news_article', 'sustainable-tourism', 'Supporting a more sustainable tourism industry', 2, '{"type":"story","slug":"sustainable-tourism","category":"Tourism News","date":"September 8, 2026","dateTime":"2026-09-08","title":"Supporting a more sustainable tourism industry","description":"Helping hotels and resorts improve energy efficiency.","source":"Department of Energy","initials":"DOE","href":"https://doe.gov.ph/news/press-releases/doe-dot-help-tourism-establishment-cut-energy-costs-improve-efficiency","image":{"src":"https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":null,"article":{"intro":"Hotels and resorts are receiving support to use energy more efficiently while maintaining the comfort guests expect.","heading":"Practical support for tourism businesses","body":"The Department of Energy and Department of Tourism initiative combines energy assessments, technical guidance, and information about financing. The DOE reported on-ground assessments at 46 tourism establishments in Metro Manila.","takeaway":"The program focuses on how accommodation businesses operate. It is not a certification that every participating property has already met a particular environmental standard.","points":["Energy assessments help identify improvement opportunities","Technical assistance supports practical changes","Guest comfort remains part of the program''s focus"],"outlook":"When choosing accommodation, ask about specific environmental practices and services that matter to your stay."}}'::jsonb, null),
  ('news_article', 'immigration-roadmap', 'A roadmap for modern immigration services', 3, '{"type":"story","slug":"immigration-roadmap","category":"Policy Updates","date":"July 8, 2026","dateTime":"2026-07-08","title":"A roadmap for modern immigration services","description":"The BI''s long-term plan for digital services and efficient public support.","source":"Bureau of Immigration","initials":"BI","href":"https://immigration.gov.ph/bi-launches-2026-2040-strategy-to-strengthen-border-security-modernize-immigration-services/","image":{"src":"/header-rizal-park.png","alt":"","mediaId":null},"logo":{"src":"/bi-logo-v2.png","alt":"Bureau of Immigration","mediaId":null},"article":{"intro":"The Bureau of Immigration''s 2026–2040 strategy sets out a long-term direction for modernizing the agency.","heading":"A long-term service roadmap","body":"The strategy was launched on July 6, 2026. Its priorities include digital transformation, border control, cybersecurity, institutional accountability, and partnerships with other agencies.","takeaway":"A strategic roadmap sets priorities over time. Travelers should continue to consult current official procedures for their specific application or arrival.","points":["Digital services are a strategic priority","The roadmap includes cybersecurity and accountability","Implementation updates should be checked through official channels"],"outlook":"Follow the bureau''s published notices for specific changes as its modernization work progresses."}}'::jsonb, null),
  ('news_article', 'discover-philippines', 'Discover more of the Philippines', 100, '{"type":"guide","date":"","dateTime":"","initials":"","category":"Travel & Events","slug":"discover-philippines","title":"Discover more of the Philippines","description":"Explore destinations and find inspiration for your next island escape.","href":"https://philippines.travel/","source":"Philippines Travel","image":{"src":"https://images.unsplash.com/photo-1518509562904-e7ef99cdcc86?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":null,"article":{"intro":"An island escape can begin with a simple question: what kind of experience would you like to bring home?","heading":"Make room for the experience","body":"Build your itinerary around your interests, whether that means relaxed beach days, city exploration, or time outdoors. Allow space between activities so transfers and rest do not become an afterthought.","takeaway":"A focused itinerary can make planning easier than trying to visit many destinations in a single trip.","points":["Choose a few priorities for your trip","Allow time for transport and rest","Confirm accommodation and activity availability"],"outlook":"Share your preferred dates and travel style with our team to discuss suitable package options."}}'::jsonb, null),
  ('news_article', 'prepare-for-your-journey', 'Prepare for your next journey', 101, '{"type":"guide","date":"","dateTime":"","initials":"","category":"Immigration","slug":"prepare-for-your-journey","title":"Prepare for your next journey","description":"Find official passport information before planning your trip abroad.","href":"https://consular.dfa.gov.ph/passport","source":"Department of Foreign Affairs","image":{"src":"https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":null,"article":{"intro":"Organizing your travel documents early gives you more time to ask questions and prepare for your plans.","heading":"Start with official information","body":"Use the Department of Foreign Affairs passport resources as a starting point for Philippine passport information. For a specific destination, consult its official immigration or consular website for the requirements that apply to you.","takeaway":"Documents depend on your destination and circumstances. A general planning article is not a personalized requirements list.","points":["Keep your itinerary and documents organized","Use official channels for application information","Check details before committing to travel arrangements"],"outlook":"Our team can help you identify the next steps to discuss for your intended trip."}}'::jsonb, null),
  ('news_article', 'responsible-travel', 'Explore responsible travel', 102, '{"type":"guide","date":"","dateTime":"","initials":"","category":"Tourism News","slug":"responsible-travel","title":"Explore responsible travel","description":"Discover the UN Tourism resources on sustainable tourism.","href":"https://www.unwto.org/sustainable-development","source":"UN Tourism","image":{"src":"https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=900&q=85","alt":"","mediaId":null},"logo":null,"article":{"intro":"Thoughtful travel starts with considering the places and communities that make a journey special.","heading":"Small choices throughout your trip","body":"Consider how you use resources, interact with local communities, and explore natural places. Ask providers about their practices rather than relying on broad environmental labels alone.","takeaway":"Responsible travel is an ongoing set of choices, from planning your stay to following guidance at the places you visit.","points":["Respect local guidance and shared spaces","Avoid unnecessary waste where practical","Ask accommodation providers about specific practices"],"outlook":"Explore UN Tourism''s sustainable development resources for a wider view of the topic."}}'::jsonb, null)
on conflict (kind, slug) do nothing;

-- ---------------------------------------------------------------------------
-- 3. Testimonials: copy the live table (published rows), else the site fallbacks
-- ---------------------------------------------------------------------------
insert into public.cms_documents (kind, slug, title, sort_order, draft)
select 'testimonial',
       coalesce(nullif(trim(both '-' from regexp_replace(lower(t.client_name), '[^a-z0-9]+', '-', 'g')), ''), 'testimonial')
         || '-' || (row_number() over (order by t.sort_order, t.created_at)),
       t.client_name,
       (row_number() over (order by t.sort_order, t.created_at))::int - 1,
       jsonb_build_object('clientName', t.client_name, 'quote', t.quote,
                          'serviceCategory', t.service_category,
                          'photo', case when t.photo_url is null then null
                                        else jsonb_build_object('src', t.photo_url, 'alt', t.client_name, 'mediaId', null) end)
from public.testimonials t
where t.is_published
on conflict (kind, slug) do nothing;

insert into public.cms_documents (kind, slug, title, sort_order, draft)
select 'testimonial', v.slug, v.title, v.sort_order, v.draft
from (values
  ('maria-santos-1', 'Maria Santos', 0, '{"clientName":"Maria Santos","quote":"Air Fair helped me get my Japan visa in just 2 weeks! Their preparation and support were professional and honest.","serviceCategory":"Tourist Visa","photo":null}'::jsonb),
  ('james-reyes-2', 'James Reyes', 1, '{"clientName":"James Reyes","quote":"They handled my 9G work visa from the employer paperwork to the BI interview. Smooth from start to finish.","serviceCategory":"9G Work Visa","photo":null}'::jsonb),
  ('ana-cruz-3', 'Ana Cruz', 2, '{"clientName":"Ana Cruz","quote":"They processed my 13A marriage visa without any hassle. The team is knowledgeable, patient, and kept me updated throughout.","serviceCategory":"13A Visa","photo":null}'::jsonb)
) as v(slug, title, sort_order, draft)
where not exists (select 1 from public.cms_documents d where d.kind = 'testimonial')
on conflict (kind, slug) do nothing;

