-- ---------------------------------------------------------------------------
-- 5. CRM routing: every form creates a lead (newsletter is not a form)
-- ---------------------------------------------------------------------------
insert into public.form_field_mappings (form_type, auto_create_contact, maps_to_category, field_mapping)
values
  ('website-contact', true, 'General', '{}'::jsonb),
  ('visa-inquiry', true, 'Visa', '{}'::jsonb),
  ('travel-inquiry', true, 'Tour Package', '{}'::jsonb),
  ('immigration-13a-immigrant-visa', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-9g-working-visa', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-tourist-visa-extension', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-acr-i-card', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-special-non-immigrant-visa', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-naturalization', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-deportation-assistance', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-visa-reconsideration', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-consultation', true, 'Immigration Processing', '{}'::jsonb),
  ('immigration-special-resident-retirees-visa', true, 'Immigration Processing', '{}'::jsonb)
on conflict (form_type) do nothing;

-- ---------------------------------------------------------------------------
-- 6. Publish everything that has never been published
-- ---------------------------------------------------------------------------
do $$
begin
  perform public.cms_publish(
    array(select id from public.cms_documents where published_version_id is null and not is_archived),
    'Initial import of existing site content (Phase 3)'
  );
end;
$$;


